package wrv.magic.retention;
import java.io.*;import java.nio.channels.*;import java.nio.file.*;import java.security.*;import java.util.*;
/** Offline candidate. Trusted adapter must provide exact immutable effective-action receipts. No SP writes. */
public final class BoundedPractice implements AutoCloseable {
 public enum EffectiveKind { DIRECT_HEAL,HOSTILE_DAMAGE,HOSTILE_CONTROL,DIRECT_CLEANSE }
 /** Zero interval/daily cap means no added gameplay throttle; receipt authority/capacity and counter overflow remain enforced. */
 public record Config(List<Long> cumulativeThresholds,Set<EffectiveKind> acceptedKinds,long minimumIntervalMillis,int dailyCap,int receiptCapacity){
  public Config{cumulativeThresholds=List.copyOf(cumulativeThresholds);acceptedKinds=Collections.unmodifiableSet(EnumSet.copyOf(acceptedKinds));if(cumulativeThresholds.size()>63||acceptedKinds.isEmpty()||minimumIntervalMillis<0||dailyCap<0||receiptCapacity<1||(dailyCap>0&&receiptCapacity<dailyCap))throw new IllegalArgumentException("invalid explicit policy");long last=0;for(long n:cumulativeThresholds){if(n<=last)throw new IllegalArgumentException("threshold order");last=n;}}
 }
 public record EffectiveUse(UUID castId,String ownerScope,String spell,UUID target,EffectiveKind kind,boolean cancelled,boolean eligibleTarget,boolean effective,long trustedTimeMillis){public EffectiveUse{Objects.requireNonNull(castId);Objects.requireNonNull(target);Objects.requireNonNull(kind);key(ownerScope);key(spell);if(trustedTimeMillis<0)throw new IllegalArgumentException("time");}}
 public enum Result { CREDITED,DUPLICATE,INEFFECTIVE,RATE_LIMIT,DAILY_CAP,CAPACITY }
 private record Progress(long count,long lastTime,long day,int today){}
 public interface Fault{void at(String stage)throws IOException;}
 private final Fault fault;
 private final Path path;private final FileChannel channel;private final FileLock lock;private final Config config;private final String policyId;private final String spell;private static final java.time.ZoneId DAY_ZONE=java.time.ZoneId.of("America/Chicago");
 private record FloorImport(String scope,int level){}
 private Map<String,Integer> floors=new TreeMap<>();private Map<String,FloorImport> migrations=new TreeMap<>();
 private record ReceiptRecord(AuthenticatedWindow.Token token,String fingerprint,String eventIdentity,Result result){}
 private Map<String,Progress> progress=new TreeMap<>();private Map<UUID,ReceiptRecord> receipts=new HashMap<>();private byte[] expected;private boolean locked,closed;
 public BoundedPractice(Path path,String policyId,String spell,Config config)throws IOException{this(path,policyId,spell,config,s->{});}
 public BoundedPractice(Path path,String policyId,String spell,Config config,Fault fault)throws IOException{this.fault=Objects.requireNonNull(fault);key(policyId);key(spell);this.spell=spell;this.policyId=policyId;this.config=Objects.requireNonNull(config);this.path=path.toAbsolutePath();Files.createDirectories(this.path.getParent());channel=FileChannel.open(this.path.resolveSibling(this.path.getFileName()+".lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);FileLock l;try{l=channel.tryLock();}catch(Exception e){channel.close();throw new IOException("owned",e);}if(l==null){channel.close();throw new IOException("owned");}lock=l;try{expected=Files.exists(this.path)?Files.readAllBytes(this.path):null;if(expected!=null)decode(expected);}catch(Exception e){close();throw new IOException("invalid usage ledger",e);}}
 /** One credit per successful CAST, never per arc/victim. Rejected cast IDs are retained too. */
 public Result recordIssued(AuthenticatedWindow issuer,AuthenticatedWindow.Token token,String fingerprint,EffectiveUse event)throws IOException{Objects.requireNonNull(issuer);Objects.requireNonNull(event);synchronized(issuer){synchronized(this){ready();if(!issuer.isOpenUseful(token,"first-use",fingerprint)||!token.spell().equals(event.spell()))throw new IOException("effect authority mismatch");return record(event,token,fingerprint);}}}
 private Result record(EffectiveUse event,AuthenticatedWindow.Token token,String fingerprint)throws IOException{ready();if(!event.spell.equals(spell)||!config.acceptedKinds.contains(event.kind))return Result.INEFFECTIVE;for(var entry:receipts.entrySet())if(entry.getValue().token.equals(token)&&!entry.getKey().equals(event.castId))throw new IOException("token already bound to another cast");ReceiptRecord prior=receipts.get(event.castId);if(prior!=null){if(!prior.token.equals(token)||!prior.fingerprint.equals(fingerprint)||!prior.eventIdentity.equals(eventIdentity(event)))throw new IOException("token/scope/effect result association conflict");return prior.result;}if(receipts.size()>=config.receiptCapacity)return Result.CAPACITY;
  // No air/cancel/immune success qualifies. Such observations do not finalize cast: later valid arc may qualify.
  if(event.cancelled||!event.eligibleTarget||!event.effective)return Result.INEFFECTIVE;
  String k=event.ownerScope+"/"+event.spell;Progress old=progress.getOrDefault(k,new Progress(0,-1,-1,0));long day=day(event.trustedTimeMillis);int today=day==old.day?old.today:0;
  Result result=old.lastTime>=0&&(event.trustedTimeMillis<old.lastTime||event.trustedTimeMillis-old.lastTime<config.minimumIntervalMillis)?Result.RATE_LIMIT:config.dailyCap>0&&today>=config.dailyCap?Result.DAILY_CAP:Result.CREDITED;
  Map<String,Progress> next=new TreeMap<>(progress);Map<UUID,ReceiptRecord> nextReceipts=new HashMap<>(receipts);nextReceipts.put(event.castId,new ReceiptRecord(token,fingerprint,eventIdentity(event),result));
  if(result==Result.CREDITED){if(old.count==Long.MAX_VALUE||today==Integer.MAX_VALUE)throw new IllegalStateException("count exhausted");next.put(k,new Progress(old.count+1,event.trustedTimeMillis,day,today+1));}
  if(next.size()>100000)throw new IOException("scope capacity");persist(next,nextReceipts,floors,migrations);progress=next;receipts=nextReceipts;return result;
 }
 /** Exact authenticated terminal proof only; retains all progress and migration data. */
 public boolean prune(AuthenticatedWindow issuer,AuthenticatedWindow.Token token,UUID cast)throws IOException{synchronized(issuer){synchronized(this){ready();ReceiptRecord prior=receipts.get(cast);if(prior==null)return false;if(!prior.token.equals(token))throw new IOException("wrong receipt token");if(!issuer.isRetired(token))return false;var next=new HashMap<>(receipts);next.remove(cast);persist(progress,next,floors,migrations);receipts=next;return true;}}}
 /** Read-only exact durable association for explicit recovery; does not authorize replay or issuer settlement. */
 public synchronized Optional<Result> recordedOutcome(AuthenticatedWindow.Token token,UUID cast,String fingerprint,EffectiveUse event)throws IOException{ready();var r=receipts.get(cast);if(r==null)return Optional.empty();if(!r.token.equals(token)||!r.fingerprint.equals(fingerprint)||!r.eventIdentity.equals(eventIdentity(event)))throw new IOException("result association mismatch");return Optional.of(r.result);}
 public record RetainedBinding(AuthenticatedWindow.Token token,UUID cast){}
 /** Bounded by explicit receiptCapacity; inspection does not itself authorize deletion. */
 public synchronized List<RetainedBinding> retainedBindings(){ready();return receipts.entrySet().stream().map(e->new RetainedBinding(e.getValue().token,e.getKey())).toList();}
 public synchronized int retainedReceipts(){ready();return receipts.size();}
 public synchronized long count(String scope){ready();key(scope);return progress.getOrDefault(scope+"/"+spell,new Progress(0,-1,-1,0)).count;}
 public synchronized int level(String scope){long count=count(scope);int level=1;for(long threshold:config.cumulativeThresholds)if(count>=threshold)level++;return Math.max(level,floors.getOrDefault(scope,1));}
 /** One coherent read for display; no progression or policy mutation. */
 public record PracticeView(String ownerScope,String spellKey,int learnedLevel,int maxLevel,long usefulCount,Long nextCumulativeThreshold,int migrationFloor,String policyId){}
 public synchronized PracticeView snapshot(String scope){
  ready();key(scope);long count=progress.getOrDefault(scope+"/"+spell,new Progress(0,-1,-1,0)).count;
  int floor=floors.getOrDefault(scope,1),learned=1;for(long threshold:config.cumulativeThresholds)if(count>=threshold)learned++;
  learned=Math.max(learned,floor);int max=config.cumulativeThresholds.size()+1;
  Long next=learned>=max?null:config.cumulativeThresholds.get(learned-1);
  return new PracticeView(scope,spell,learned,max,count,next,floor,policyId);
 }
 /** Reviewed migration floor, NOT fabricated historical useful casts. Receipt replay is idempotent. */
 public synchronized boolean importFloor(String scope,int level,String migrationReceipt)throws IOException{ready();key(scope);key(migrationReceipt);if(level<1||level>config.cumulativeThresholds.size()+1)throw new IllegalArgumentException("floor outside policy");FloorImport request=new FloorImport(scope,level);FloorImport existing=migrations.get(migrationReceipt);if(existing!=null){if(!existing.equals(request))throw new IllegalStateException("migration receipt conflict");return false;}if(migrations.size()>=100000)throw new IllegalStateException("migration capacity");Map<String,Integer> nf=new TreeMap<>(floors);nf.merge(scope,level,Math::max);Map<String,FloorImport> nm=new TreeMap<>(migrations);nm.put(migrationReceipt,request);persist(progress,receipts,nf,nm);floors=nf;migrations=nm;return true;}
 private static long day(long millis){return java.time.Instant.ofEpochMilli(millis).atZone(DAY_ZONE).toLocalDate().toEpochDay();}
 private static void key(String x){if(x==null||x.isBlank()||x.length()>200||x.contains("/")||x.indexOf('\0')>=0)throw new IllegalArgumentException("key");}
 private void ready(){if(locked||closed)throw new IllegalStateException("persistence uncertain or closed");try{if(!Arrays.equals(expected,Files.exists(path)?Files.readAllBytes(path):null)){locked=true;throw new IllegalStateException("external state change");}}catch(IOException e){locked=true;throw new IllegalStateException("state unavailable",e);}}
 private static byte[] hash(byte[] b){try{return MessageDigest.getInstance("SHA-256").digest(b);}catch(Exception e){throw new AssertionError(e);}}
 private String policy(){return policyId+"|"+spell+"|"+DAY_ZONE+"|"+config.toString();}
 private byte[] encode(Map<String,Progress> ps,Map<UUID,ReceiptRecord> rs,Map<String,Integer> fs,Map<String,FloorImport> ms)throws IOException{var bytes=new ByteArrayOutputStream();try(var d=new DataOutputStream(bytes)){d.writeInt(0x55535033);d.writeInt(3);d.writeUTF(policy());d.writeInt(ps.size());for(var entry:ps.entrySet()){d.writeUTF(entry.getKey());Progress p=entry.getValue();d.writeLong(p.count);d.writeLong(p.lastTime);d.writeLong(p.day);d.writeInt(p.today);}d.writeInt(rs.size());for(UUID id:new TreeSet<>(rs.keySet())){d.writeLong(id.getMostSignificantBits());d.writeLong(id.getLeastSignificantBits());ReceiptRecord r=rs.get(id);writeToken(d,r.token);d.writeUTF(r.fingerprint);d.writeUTF(r.eventIdentity);d.writeUTF(r.result.name());}d.writeInt(fs.size());for(var e:fs.entrySet()){d.writeUTF(e.getKey());d.writeInt(e.getValue());}d.writeInt(ms.size());for(var e:ms.entrySet()){d.writeUTF(e.getKey());d.writeUTF(e.getValue().scope);d.writeInt(e.getValue().level);}}byte[] body=bytes.toByteArray();bytes.write(hash(body));return bytes.toByteArray();}
 private void decode(byte[] bytes)throws IOException{if(bytes.length<44||bytes.length>64*1024*1024)throw new IOException("length");byte[] body=Arrays.copyOf(bytes,bytes.length-32);if(!MessageDigest.isEqual(hash(body),Arrays.copyOfRange(bytes,bytes.length-32,bytes.length)))throw new IOException("checksum");try(var d=new DataInputStream(new ByteArrayInputStream(body))){if(d.readInt()!=0x55535033||d.readInt()!=3||!d.readUTF().equals(policy()))throw new IOException("schema/policy mismatch: explicit migration required");int n=d.readInt();if(n<0||n>100000)throw new IOException("progress bounds");for(int i=0;i<n;i++){String k=d.readUTF();if(!k.endsWith("/"+spell))throw new IOException("spell key");key(k.substring(0,k.length()-("/"+spell).length()));Progress p=new Progress(d.readLong(),d.readLong(),d.readLong(),d.readInt());if(p.count<1||p.lastTime<0||p.day!=day(p.lastTime)||p.today<1||(config.dailyCap>0&&p.today>config.dailyCap)||progress.put(k,p)!=null)throw new IOException("progress");}n=d.readInt();if(n<0||n>config.receiptCapacity)throw new IOException("receipt bounds");for(int i=0;i<n;i++){UUID id=new UUID(d.readLong(),d.readLong());var token=readToken(d);String fingerprint=d.readUTF(),event=d.readUTF();Result result=Result.valueOf(d.readUTF());if(!fingerprint.matches("[a-f0-9]{64}")||!event.matches("[a-f0-9]{64}")||!Set.of(Result.CREDITED,Result.RATE_LIMIT,Result.DAILY_CAP).contains(result)||receipts.put(id,new ReceiptRecord(token,fingerprint,event,result))!=null)throw new IOException("receipt association");}n=d.readInt();if(n<0||n>100000)throw new IOException("floor bounds");for(int i=0;i<n;i++){String owner=d.readUTF();key(owner);int level=d.readInt();if(level<1||level>config.cumulativeThresholds.size()+1||floors.put(owner,level)!=null)throw new IOException("floor");}n=d.readInt();if(n<0||n>100000)throw new IOException("migration bounds");for(int i=0;i<n;i++){String receipt=d.readUTF(),owner=d.readUTF();key(receipt);key(owner);int level=d.readInt();if(level<1||level>floors.getOrDefault(owner,0)||migrations.put(receipt,new FloorImport(owner,level))!=null)throw new IOException("migration");}if(d.read()!=-1)throw new IOException("trailing bytes");}}
 private void persist(Map<String,Progress> ps,Map<UUID,ReceiptRecord> rs,Map<String,Integer> fs,Map<String,FloorImport> ms)throws IOException{try{byte[] onDisk=Files.exists(path)?Files.readAllBytes(path):null;if(!Arrays.equals(expected,onDisk))throw new IOException("external change");byte[] bytes=encode(ps,rs,fs,ms);if(bytes.length>64*1024*1024)throw new IOException("capacity");Path temp=Files.createTempFile(path.getParent(),"usage-",".tmp");try{fault.at("before-write");try(var c=FileChannel.open(temp,StandardOpenOption.WRITE)){var b=java.nio.ByteBuffer.wrap(bytes);while(b.hasRemaining())c.write(b);c.force(true);}fault.at("before-move");Files.move(temp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);fault.at("after-move");try(var dir=FileChannel.open(path.getParent(),StandardOpenOption.READ)){dir.force(true);}if(!Arrays.equals(Files.readAllBytes(path),bytes))throw new IOException("readback");expected=bytes;}finally{Files.deleteIfExists(temp);}}catch(IOException e){locked=true;throw e;}}
 private static String eventIdentity(EffectiveUse e)throws IOException{var raw=new ByteArrayOutputStream();try(var d=new DataOutputStream(raw)){d.writeUTF("wrv-practice-use-v2");d.writeLong(e.castId.getMostSignificantBits());d.writeLong(e.castId.getLeastSignificantBits());d.writeUTF(e.ownerScope);d.writeUTF(e.spell);d.writeLong(e.target.getMostSignificantBits());d.writeLong(e.target.getLeastSignificantBits());d.writeUTF(e.kind.name());d.writeBoolean(e.cancelled);d.writeBoolean(e.eligibleTarget);d.writeBoolean(e.effective);d.writeLong(e.trustedTimeMillis);}return HexFormat.of().formatHex(hash(raw.toByteArray()));}
 private static void writeToken(DataOutputStream d,AuthenticatedWindow.Token t)throws IOException{d.writeUTF(t.lineage().toString());d.writeLong(t.epoch());d.writeLong(t.sequence());d.writeUTF(t.caster().toString());d.writeUTF(t.spell());d.writeUTF(t.sourceHash());d.writeUTF(t.capability().toString());}
 private static AuthenticatedWindow.Token readToken(DataInputStream d)throws IOException{return new AuthenticatedWindow.Token(UUID.fromString(d.readUTF()),d.readLong(),d.readLong(),UUID.fromString(d.readUTF()),d.readUTF(),d.readUTF(),UUID.fromString(d.readUTF()));}
 public synchronized void close()throws IOException{if(!closed){closed=true;try{lock.release();}finally{channel.close();}}}
}
